fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x0c0c10);
    let x0: i32 = 40;
    let bw: i32 = w - x0 - 16;
    let starts = [1, 3, 5, 8];
    let durs = [3, 4, 2, 3];
    let mut k: i32 = 0;
    while k < 13 {
        let x: i32 = x0 + k * bw / 12;
        host::display::draw_line(x, 28, x, h - 50, 0x202028);
        host::display::draw_number(x - 4, 12, k, 0x808080, 1);
        k = k + 1;
    }
    let nowx: i32 = x0 + (t % 1440) * bw / 1440;
    let mut i: i32 = 0;
    while i < 4 {
        let y: i32 = 48 + i * 60;
        let sx: i32 = x0 + starts[i] * bw / 12;
        let ex: i32 = x0 + (starts[i] + durs[i]) * bw / 12;
        let col: i32 = if nowx >= sx && nowx < ex { 0x50c0ff } else { 0x28506a };
        host::display::fill_rect(sx, y, ex - sx, 36, col);
        host::display::draw_number(8, y + 12, i + 1, 0xc0c0c0, 2);
        i = i + 1;
    }
    host::display::draw_line(nowx, 28, nowx, h - 50, 0xff4040);
    host::display::draw_string(x0, h - 32, "NOW SWEEPS THE DAY IN 24S", 0x606060, 1);
    host::display::present();
}
